function StoreComponent.IsGoodStore(dataKey)
    if dataKey == "over" or dataKey == "maze" or dataKey == "pvp"
            or dataKey == "talent" or dataKey == "fishing"
            or dataKey == "activityTalent" or dataKey == "catHousePet" then
        return true
    end
    return false
end

function StoreComponent.IsProductAttention(product)
    if product.stock == -1 then
        return false
    end

    if product.currentStock == 0 then
        return false
    end

    local free = true
    for i = 1, #product.prices do
        if product.prices[i].current ~= 0 then
            free = false
            break
        end
    end
    
    return free
end

function StoreComponent:InitialStore(jsonStr)
