function StoreComponent:FillData(jsonData)

    for k, v in pairs(jsonData) do
        if k == "recommend" then
            local listData = {}
            for i = 1, #v.recommendList do
                local dojo = StoreRecommendDojo.New()
                dojo:Fill(v.recommendList[i])
                table.insert(listData, dojo)
            end
            local data = {
                recommendList = listData,
                passCardScheduleId = v.passCardScheduleId
            }
            self.AllStores[k] = data
            --self.AllStores[k] = {}
        elseif StoreComponent.IsGoodStore(k) then
            local dojo = StoreDojo.New()
            --printInfo(table.dump(v))
            dojo:Fill(v)
            if v.activityTimeLeft ~= nil then
                if v.activityTimeLeft > 0 then
                    self.AllStores[k] = dojo
                end
            else
                self.AllStores[k] = dojo
            end
            --printInfo(table.dump(dojo))
        elseif k == "freeDiamond" or k == "diamond" then
            local listData = {}
            for i = 1, #v do
                local dojo = StoreDiamondDojo.New()
                dojo:Fill(v[i])
                table.insert(listData, dojo)
            end
            table.sort(listData, function(a, b)
                if a.pos ~= b.pos then
                    return a.pos < b.pos
                else
                    return a.productId < b.productId
                end
            end)
            self.AllStores[k] = listData
        elseif k == "chest" then
            local listData = {}
            for i = 1, #v do
                local dojo = StoreChestDojo.New()
                dojo:Fill(v[i])
                table.insert(listData, dojo)
            end
            table.sort(listData, function(a, b)
                if a.pos ~= b.pos then
                    return a.pos < b.pos
                else
                    return a.productId < b.productId
                end
            end)
            self.AllStores[k] = listData
        elseif k == "goods" then
            local listData = {}
            for i = 1, #v.products do
                v.products[i].nextRefreshLeftSeconds = v.nextRefreshLeftSeconds
                v.products[i].rewards = {
                    {num = v.products[i].num, goodsId = v.products[i].goodsId}
                }
                local dojo = StoreChestDojo.New()
                dojo:Fill(v.products[i])
                table.insert(listData, dojo)
            end
            table.sort(listData, function(a, b)
                if a.pos ~= b.pos then
                    return a.pos < b.pos
                else
                    return a.productId < b.productId
                end
            end)
            self.AllStores[k] = listData
        elseif k == "dailyGift" then
            self.AllStores[k] = v
        elseif k == "levelGift" then
            local levelGiftData = v
            -- 付费礼包
            local payData = {}
            for _, data in ipairs(levelGiftData.levelGiftsPay.giftList) do
                local dojo = StoreLevelGiftDojo.New()
                dojo:Fill(data)
                table.insert(payData, dojo)
            end
            levelGiftData.levelGiftsPay.giftList = payData
            -- 免费礼包
            local freeData = {}
            for _, data in ipairs(levelGiftData.levelGiftsFree.giftList) do
                local dojo = StoreLevelGiftDojo.New()
                dojo:Fill(data)
                table.insert(freeData, dojo)
            end
            levelGiftData.levelGiftsFree.giftList = freeData
            self.AllStores[k] = levelGiftData
        elseif k == "skin" then
            local listData = {}
            for i = 1, #v.products do
                local dojo = StoreSkinDojo.New()
                dojo:Fill(v.products[i])
                table.insert(listData, dojo)
            end
            table.sort(listData, function(a, b)
                if a.pos ~= b.pos then
                    return a.pos < b.pos
                else
                    return a.productId < b.productId
                end
            end)
            self.AllStores[k] = listData
        end
    end
end

