function StoreComponent:InitialMonthCardInfo(datas)

    self.MonthCardInfo = {}

    if self._timers ~= nil then
        for i, v in pairs(self._timers) do
            self:RemoveTimer(i)
        end
    else
        self._timers = {}
    end

    for i, v in pairs(datas) do
        ---@type StoreMonthCardDojo
        local dojo = StoreMonthCardDojo.New()
        dojo:Fill(v)
        local id = checkInt(dojo.monthCardId)
        if id == 0 then
            id = tostring(i)
        else
            id = tostring(id)
        end
        dojo.monthCard = id
        self.MonthCardInfo[id] = dojo
        self:StartTimer(id)
    end
    self:CheckMonthCardRed()
    --self:RefreshPrivilege()
end
