---@param monthId integer @ 月卡id
---@return boolean
function StoreComponent:IsMonthCardDrawRewards(monthId)

    local isDraw = false
    monthId = tostring(monthId)
    local monthData = self.MonthCardInfo[monthId]

    if not monthData then
        return isDraw
    end

    if not self:IsMonthCardActive(monthId) then
        return isDraw
    end

    if monthData:GetDrawRewards() ~= 0 then
        return isDraw
    end


    local vo = CfUtils.GetCfVo(AutoIds.IdSetting602,"MonthCardVo",monthId)
    if vo.type == MONTH_CARD_TYPE.COMMON then
        if checkInt(monthData.leftDrawnNum) == 0 then
            return isDraw
        end
    end
    return true
end

function StoreComponent:RefreshMonthCardInfo(datas)
    datas = datas or {}
    if self.MonthCardInfo == nil then
        self.MonthCardInfo = {}
    end
    printInfo(table.dump(datas))
    for i, v in pairs(datas) do
        local id = checkInt(v.monthCardId)
        if id == 0 then
            id = i
        end
        self:RemoveTimer(id)
        ---@type  StoreMonthCardDojo
        local dojo = StoreMonthCardDojo.New()
        dojo.monthCardId = id
        dojo:Fill(v)
        self.MonthCardInfo[tostring(id)] = dojo

        self:StartTimer(tostring(id))
    end
