end

function StoreComponent:CheckMonthCardRed()
    local isHaveDraw = self:IsHaveDrawRewards()
    local num = isHaveDraw and 1 or 0

    local MonthCardRed = Constants.RedPointConst.MonthCard
    GameUtils.SetRedPointNum(MonthCardRed, num)
    GameUtils.InvokeRedPointCallBack(MonthCardRed)
end
function StoreComponent:IsHaveDrawRewards()
    local isHaveDraw = false
    if self.MonthCardInfo then
        for i, dojo in pairs(self.MonthCardInfo) do
            isHaveDraw = self:IsMonthCardDrawRewards(dojo.monthCardId)
            if isHaveDraw then
                break
            end
        end
    end
    return isHaveDraw
end
function StoreComponent:RemoveTimer(key)
    if self._timers == nil then
        return
    end
    if isSet(self._timers, key) then
        CDTimerModule:RemoveCD(self._timers[key])
    end
end

function StoreComponent:StartTimer(key)
    if checkInt(key) == 0 then
        return
    end
    if self.MonthCardInfo == nil then
        return
    end
    
    if self._timers == nil then
        self._timers = {}
    end

    key = tostring(key)
    local monthCard = self.MonthCardInfo[key]
    if checkInt(monthCard.leftSeconds) <= 0 then
        return
    end
    self._timers[key] = CDTimerModule:AddCD(1, function(count, id)
        local tKey, tTimer = self:IndexOfTimer(id)
        if tKey == nil or tTimer == nil then
            return 
        end
        tKey = tostring(tKey)
        self.MonthCardInfo[tKey].leftSeconds = math.max(0, count)
    end, monthCard.leftSeconds, false, true)
    
    self._timers[key].OnRemove = function(count, id)
        local tKey, tTimer = self:IndexOfTimer(id)
        if tKey == nil or tTimer == nil then
            return
        end
        tKey = tostring(tKey)

        self.MonthCardInfo[tKey].leftSeconds = math.max(0, count)
        self._timers[tKey] = nil
        --self:RefreshPrivilege()
        
        if self.MonthCardInfo[tKey].leftSeconds == 0 then
            self.MonthCardInfo[tKey] = nil
            Events.Broadcast(Constants.EventNames.OnMonthCardExpired)
        end
    end
end

function StoreComponent:IndexOfTimer(id)
    if self._timers == nil then
        return nil, nil
    end
    for i, v in pairs(self._timers) do
        if v.Id == id then
            return i, v
        end
    end
    return nil, nil
end
function StoreComponent:IsMonthCardActive(monthCardId)
    monthCardId = tostring(monthCardId)
    if self.MonthCardInfo == nil then
        return false
    end
    if isSet(self.MonthCardInfo, monthCardId) then
        if checkInt(self.MonthCardInfo[monthCardId].leftSeconds) > 0 then
           return true
        else
            if checkInt(self.MonthCardInfo[monthCardId].endTime) == -1 then
                return true
            end
        end
    end

    return false
end

