function StoreComponent:DecreaseTime(second)
    if self.AllStores == nil then
        return
    end
    for k, v in pairs(self.AllStores) do
        if k == "recommend" then
            --for i = 1, #self.AllStores[k] do
            --    if isSet(self.AllStores[k][i], ) then
            --        
            --    end
            --end
            for i = 1, #v.recommendList do
                local store = v.recommendList[i]
                if isSet(store, RemainTime) then
                    if store[RemainTime] ~= -1 then
                        store[RemainTime] = math.max(0, store[RemainTime] - second)
                    end
                end
            end
        elseif StoreComponent.IsGoodStore(k) then
            --local dojo = StoreDojo.New()
            --dojo:Fill(v)
            --self.AllStores[k] = dojo
            local store = v
            if isSet(store, RefreshSecond) then
                if store[RefreshSecond] ~= -1 then
                    store[RefreshSecond] = math.max(0, store[RefreshSecond] - second)
                end
            end

            if isSet(store, ActivitySecond) then
                if store[ActivitySecond] ~= -1 then
                    store[ActivitySecond] = math.max(0, store[ActivitySecond] - second)
                    --printInfo("refresh %d", store[ActivitySecond])
                end
            end
            
        elseif k == "freeDiamond" or k == "diamond" then

        elseif k == "chest" or k == "goods" then
            for i = 1, #v do
                local store = v[i]
                if isSet(store, RefreshSecond) then
                    if store[RefreshSecond] ~= -1 then
                        store[RefreshSecond] = math.max(0, store[RefreshSecond] - second)
                    end
                end
            end
        end
    end
end

function StoreComponent:RefreshStock(dataKey, productId, count)
    if self.AllStores == nil then
        return false
    end
    
    if not isSet(self.AllStores, dataKey) then
        return false
    end
    
    local dojo = self:GetProductDojo(dataKey, productId)
    if dojo == nil then
        return false
    else
        if isSet(dojo, "currentStock") and isSet(dojo, "stock") then
            if dojo.stock == -1 then
                return false
            else
                dojo.currentStock = math.max(0, dojo.currentStock - count)
                local ret = StoreComponent.IsProductAttention(dojo)
                if not ret then
                    if self.FreeProducts[dataKey] ~= nil then
                        self.FreeProducts[dataKey][dojo.productId] = nil
                        if table.count(self.FreeProducts[dataKey]) == 0 then
                            self.FreeProducts[dataKey] = nil
                        end
                    end
                end

                return true
            end
        else
            if isSet(dojo, "isFirst") then
                if dojo.isFirst == 1 then
                    dojo.isFirst = 0
                    return true
                else
                    return false
                end
            end
            return false
        end

    end
end

function StoreComponent:RefreshNextChest(dataKey, productId, nextChest)
    if self.AllStores == nil then return false end

    if not isSet(self.AllStores, dataKey) then return false end
    
    local index = nil
    for i, v in ipairs(self.AllStores[dataKey]) do
        if v.productId == productId then
            index = i
            break
        end 
    end
    if index then
        table.remove(self.AllStores[dataKey], index)
    end

    local dojo = StoreChestDojo.New()
    dojo:Fill(nextChest)
    table.insert(self.AllStores[dataKey], dojo)
end

function StoreComponent:GetProductDojo(dataKey, productId)
    if self.AllStores == nil then
        return nil
    end

    if isSet(self.AllStores, dataKey) then
        if dataKey == "recommend" then
            --for i = 1, #self.AllStores[k] do
            --    if isSet(self.AllStores[k][i], ) then
            --        
            --    end
            --end
            --recommendList 没有库存 使用实际的id 做更新
            return nil
        elseif StoreComponent.IsGoodStore(dataKey) then
            --local dojo = StoreDojo.New()
            --dojo:Fill(v)
            --self.AllStores[k] = dojo
            --printInfo(dataKey)
            local store = self.AllStores[dataKey]
            local dojo
            for i = 1, #store.products do
                if store.products[i].productId == productId then
                    dojo = store.products[i]
                    break;
                end
            end
            --printInfo(dojo)

            return dojo

        elseif dataKey == "freeDiamond" or dataKey == "diamond" then

            local store = self.AllStores[dataKey]
            local dojo
            for i = 1, #store do
                if store[i].productId == productId then
                    dojo = store[i]
                    break;
                end
            end

            return dojo

        elseif dataKey == "chest" then
            
            local store = self.AllStores[dataKey]
            local dojo
            for i = 1, #store do
                if store[i].productId == productId then
                    dojo = store[i]
                    break;
                end
            end

            return dojo
        elseif dataKey == "goods" then
            local store = self.AllStores[dataKey]
            local dojo
            for i = 1, #store do
                if store[i].productId == productId then
                    dojo = store[i]
                    break;
                end
            end

            return dojo
        elseif dataKey == "skin" then
            local store = self.AllStores[dataKey]
            local dojo
            for i = 1, #store do
                if store[i].productId == productId then
                    dojo = store[i]
                    break;
                end
            end

            return dojo
        end
    end
    return nil
end



