function StoreComponent:GetNormalMonthCardData()
    for i, v in pairs(self.MonthCardInfo) do
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , v.monthCardId)
        if vo.type == MONTH_CARD_TYPE.COMMON then
            return v
        end
    end
    return nil
end

function StoreComponent:IsNeedPopUpMonthCard()
    local isPopUp = false
    for i, v in pairs(self.MonthCardInfo) do
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting602, "MonthCardVo" , v.monthCardId)
        if vo.type == MONTH_CARD_TYPE.COMMON then
            if v.isRenew == 1 then
                local lastPopUpMonthCardTime = checkNumber(CfUtils.GetLocalData("LastPopUpMonthCardTime"))
                local time = os.time()
                local t = timestamp_to_time(time)
                if checkNumber(t.day) ~= checkNumber(lastPopUpMonthCardTime) then
                    isPopUp = true
                end
            end
        end
    end
    return isPopUp
end


